WITH src AS (SELECT *, CASE WHEN txn_type = 'CREDIT' THEN 1 ELSE 0 END AS is_credit FROM transactions WHERE account_id IN (3, 22, 33) AND amount BETWEEN 3700 AND 3900), agg AS (SELECT is_flagged, HOUR(txn_time) AS txn_hour, AVG(is_credit) AS avg_is_credit FROM src GROUP BY is_flagged, HOUR(txn_time)) SELECT is_flagged, txn_hour FROM agg WHERE avg_is_credit > 24 ORDER BY txn_hour DESC;
